import{_ as n,C as o,o as s,c as l,a2 as t,E as r}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Marketplace Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/overview.md","filePath":"configuration/overview.md","lastUpdated":1789411447000}'),i={name:"configuration/overview.md"};function h(d,e,g,c,p,u){const a=o("ImagePopup");return s(),l("div",null,[e[0]||(e[0]=t('<h1 id="marketplace-configuration" tabindex="-1">Marketplace Configuration <a class="header-anchor" href="#marketplace-configuration" aria-label="Permalink to &quot;Marketplace Configuration&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>The marketplace adds its own settings to the admin&#39;s <strong>Configure</strong> page. They decide how sellers join, what they can do with products and orders, how the storefront presents the marketplace, and how sellers use Generative AI.</p><h2 id="open-the-marketplace-settings" tabindex="-1">Open the marketplace settings <a class="header-anchor" href="#open-the-marketplace-settings" aria-label="Permalink to &quot;Open the marketplace settings&quot;">​</a></h2><ol><li>In the admin panel, go to <strong>Configure</strong>.</li><li>Under <strong>Marketplace</strong>, click the tile for the settings you want.</li></ol>',5)),r(a,{src:"/images/configuration/configuration-marketplace-tiles.png",alt:"The Marketplace group of tiles on the Configure page"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Tile</th><th>What it controls</th></tr></thead><tbody><tr><td><a href="./general">General</a></td><td>Turning the marketplace on, the default commission, the Seller Panel logo and subscription plans</td></tr><tr><td><a href="./sellers">Sellers</a></td><td>Seller approval and visibility, what sellers can do with orders, and upload size</td></tr><tr><td><a href="./products">Products</a></td><td>Product approval, whether sellers create or resell products, the product form and the low-stock level</td></tr><tr><td><a href="./moderation-and-health">Moderation &amp; Health</a></td><td>Reporting of products and sellers, the red flag, and account-health thresholds</td></tr><tr><td><a href="./marketing">Marketing</a></td><td>Whether sellers can join admin product discounts, and how join requests are approved</td></tr><tr><td><a href="./fulfilment-carriers">Fulfilment Carriers</a></td><td>The couriers sellers use to ship orders</td></tr><tr><td><a href="./featured-sellers">Featured Sellers</a></td><td>The featured sellers shown on the marketplace landing page</td></tr><tr><td><a href="./landing-page">Landing Page</a></td><td>The banner, highlights, features and seller journey on the landing page</td></tr></tbody></table><p>The settings for Generative AI sit in the <strong>Magic AI</strong> group of the same page, on the <strong>Marketplace Features</strong> tile. See <a href="./generative-ai">Generative AI Configuration</a>.</p>',2)),r(a,{src:"/images/configuration/configuration-magic-ai-tiles.png",alt:"The Magic AI group with the Marketplace Features tile"}),e[2]||(e[2]=t('<h2 id="settings-per-channel-and-per-language" tabindex="-1">Settings per channel and per language <a class="header-anchor" href="#settings-per-channel-and-per-language" aria-label="Permalink to &quot;Settings per channel and per language&quot;">​</a></h2><p>A setting can apply to the whole store, to one channel, or to one language:</p><ul><li>A field labelled with a channel name, such as <strong>Default</strong>, is saved for each channel.</li><li>A field labelled with a language, such as <strong>English</strong>, is saved for each language.</li><li>A field without a label applies everywhere.</li></ul><p>Choose the channel or language at the top of the screen before you change these fields. Each selector only appears when your store has more than one channel or language.</p><h2 id="save-your-changes" tabindex="-1">Save your changes <a class="header-anchor" href="#save-your-changes" aria-label="Permalink to &quot;Save your changes&quot;">​</a></h2><p>Click <strong>Save Configuration</strong> at the top of the screen. Saving marketplace settings also refreshes the storefront pages the marketplace keeps in its cache, so customers see the change straight away.</p><h3 id="turning-the-marketplace-off" tabindex="-1">Turning the marketplace off <a class="header-anchor" href="#turning-the-marketplace-off" aria-label="Permalink to &quot;Turning the marketplace off&quot;">​</a></h3><p><strong>Status</strong> on the <a href="./general">General</a> screen switches the whole marketplace on or off. While it is off:</p><ul><li>the <strong>Marketplace</strong> menu disappears from the admin panel;</li><li>the Seller Panel and the marketplace storefront pages are unavailable;</li><li>seller products are hidden from the storefront and can&#39;t be bought.</li></ul><p>Your data is kept, and everything returns when you switch it back on.</p><h2 id="settings-in-the-marketplace-menu" tabindex="-1">Settings in the Marketplace menu <a class="header-anchor" href="#settings-in-the-marketplace-menu" aria-label="Permalink to &quot;Settings in the Marketplace menu&quot;">​</a></h2><p>Two lists that work like settings sit in the admin sidebar under <strong>Marketplace &gt;&gt; Configure</strong>, not on the Configure page:</p><ul><li><strong>Flag Reasons</strong> — the reasons customers choose when they report a product or seller. See <a href="./../moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li><li><strong>Inventory Sources</strong> — a read-only list of every seller&#39;s inventory sources. See <a href="./../inventory/inventory-source-management">Inventory Sources</a>.</li></ul><h2 id="who-can-change-these-settings" tabindex="-1">Who can change these settings <a class="header-anchor" href="#who-can-change-these-settings" aria-label="Permalink to &quot;Who can change these settings&quot;">​</a></h2><p>Anyone whose admin role includes <strong>Configure</strong> can open and save the marketplace tiles. The marketplace doesn&#39;t add a separate permission for them.</p>',15))])}const k=n(i,[["render",h]]);export{m as __pageData,k as default};
